  [UnityTest,Timeout(190000)]public IEnumerator FourRealAiCollectPourSettleServeBowFinishPauseAndRematch(){using(var f=new Fixture()){yield return f.Load();f.Start();string id=(string)Get(f.match,"MatchId");Time.timeScale=3;bool held=false,pause=false,capture=false;float end=Time.realtimeSinceStartup+145;while(!(bool)Get(f.match,"Finished")&&Time.realtimeSinceStartup<end){f.Observe();held|=f.arms.Any(a=>Get(a,"Held")!=null);if(held&&!pause){pause=true;Call(f.match,"Pause",0,false);float clock=(float)Get(f.rules,"Clock");var volumes=f.pots.Concat(f.cups.Select(c=>Get(c,"vessel"))).Select(v=>(float)Get(v,"Volume")).ToArray();var poses=f.trucks.Select(Body).Select(b=>b.position).ToArray();yield return new WaitForSecondsRealtime(.2f);Assert.That((float)Get(f.rules,"Clock"),Is.EqualTo(clock));Assert.That(f.pots.Concat(f.cups.Select(c=>Get(c,"vessel"))).Select(v=>(float)Get(v,"Volume")),Is.EqualTo(volumes));for(int i=0;i<4;i++)Assert.That(Vector3.Distance(poses[i],Body(f.trucks[i]).position),Is.LessThan(.001f));Call(f.match,"Resume");Time.timeScale=3;}if(!capture&&(int)Get(f.match,"ActualServings")>0){capture=true;Time.timeScale=1;yield return Capture(f.match,"natural-AI-service-720",1280,720);yield return Capture(f.match,"natural-AI-service-1080",1920,1080);Time.timeScale=3;}yield return null;}
   Assert.That((bool)Get(f.match,"Finished"),Is.True);Assert.That(held&&pause&&capture,Is.True);Assert.That((int)Get(f.match,"ActualPours"),Is.GreaterThan(0),"Actual ballistic receiver hits must precede service.");Assert.That((int)Get(f.match,"ActualServings"),Is.GreaterThan(0),"AI must physically release a filled intact cup onto the correct native table.");Assert.That(((int[])Get(f.rules,"bows")).Sum(),Is.GreaterThan(0),"An actual nearby completed serving-arm bow is required.");Assert.That((int)Get(Get(f.match,"ScoreJournal"),"Count"),Is.GreaterThan(0));f.Start();Assert.That((string)Get(f.match,"MatchId"),Is.Not.EqualTo(id));Assert.That((int[])Get(f.rules,"points"),Is.All.Zero);Assert.That(f.pots.All(v=>!(bool)Get(v,"Broken")&&Mathf.Abs((float)Get(v,"Volume")-(float)Get(v,"initialVolume"))<.001f),Is.True);}}
  [UnityTest,Timeout(65000)]public IEnumerator RealAiCarriesFullCupWithinOriginalArmReachAndActuallySettlesServiceAndBow(){using(var f=new Fixture()){yield return f.Load();f.Start();Time.timeScale=2;bool observedPlacement=false;float end=Time.realtimeSinceStartup+50;while(((int[])Get(f.rules,"bows")).Sum()==0&&Time.realtimeSinceStartup<end){f.Observe();var states=(int[])Get(f.match,"state");for(int i=0;i<4;i++)if(states[i]==5||states[i]==10){var held=Get(f.arms[i],"Held");Assert.That(held,Is.Not.Null,"Physical filled cup remains held through the reachable placement approach.");var cupIndex=i*3+((int[])Get(f.match,"currentCup"))[i];var cup=f.cups[cupIndex];var guest=((Array)Get(f.match,"guests")).GetValue((int)Get(cup,"guestId"));var target=(Vector3)Call(f.match,"ServicePlacement",cup);if(states[i]==5)target+=Vector3.up*1.3f;var grip=(Rigidbody)Get(f.arms[i],"grip");var requiredGrip=target-(Body(held).position-grip.position);var root=((Component)f.trucks[i]).transform;var mount=root.TransformPoint((Vector3)Get(f.arms[i],"mount"));Assert.That(Vector3.Distance(mount,requiredGrip),Is.LessThanOrEqualTo(8.01f),"Actual current held-body offset must fit the unchanged8m workspace; no teleport or longer arm.");var table=(Collider)Get(guest,"table");Assert.That(((Collider)Get(f.trucks[i],"shape")).bounds.max.z,Is.LessThan(table.bounds.min.z+.05f),"Original full NWH hull stays in front of the physical guest table.");observedPlacement=true;}for(int i=0;i<4;i++)if(states[i]==11||states[i]==6){var index=i*3+((int[])Get(f.match,"currentCup"))[i];if(index<12){var v=Get(f.cups[index],"vessel");Assert.That(Vector3.Dot(((Component)v).transform.up,Vector3.up),Is.GreaterThan(.9f),"The actually released cup must remain upright during horizontal-away withdrawal and native tabletop settlement.");}}yield return null;}Assert.That(observedPlacement,Is.True);Assert.That((int)Get(f.match,"ActualServings"),Is.GreaterThan(0));Assert.That(((int[])Get(f.rules,"bows")).Sum(),Is.GreaterThan(0));var served=f.cups.Select(c=>Get(c,"vessel")).Where(v=>(bool)Get(v,"Banked")).ToArray();Assert.That(served.Length,Is.GreaterThan(0));foreach(var v in served){Assert.That(Get(v,"Holder"),Is.Null);Assert.That((float)Get(v,"Volume"),Is.GreaterThanOrEqualTo(.75f));Assert.That((bool)Get(v,"Broken"),Is.False);Assert.That((int)Get(v,"LastCarrier"),Is.InRange(0,3));}TestContext.WriteLine("TEA_REACHABLE_NATIVE actual cup service and courtesy; original8m articulation, native table support and scoring gates unchanged.");}}
  [UnityTest,Timeout(30000)]public IEnumerator ActualNativeTableSupportPersistsWhileSleepingAndExpiresAfterPhysicalSeparation(){using(var f=new Fixture()){yield return f.Load();f.Start(1);yield return Until(()=>(bool)Get(f.rules,"Active"),8,"Original countdown.");f.match.enabled=false;foreach(var truck in f.trucks)Call(truck,"Power",false);var cup=f.cups[0];var v=Get(cup,"vessel");var body=Body(v);float mass=body.mass;var guest=((Array)Get(f.match,"guests")).GetValue(0);var table=(Collider)Get(guest,"table");var target=(Vector3)Call(f.match,"ServicePlacement",cup);body.position=target+Vector3.up;body.rotation=Quaternion.identity;body.transform.SetPositionAndRotation(body.position,body.rotation);body.linearVelocity=body.angularVelocity=Vector3.zero;body.WakeUp();Physics.SyncTransforms();float deadline=Time.realtimeSinceStartup+8;while((Get(v,"LastSupport")as Collider!=table||!body.IsSleeping())&&Time.realtimeSinceStartup<deadline){Call(v,"TickLiquid",Time.fixedDeltaTime);yield return new WaitForFixedUpdate();}Assert.That(Get(v,"LastSupport"),Is.SameAs(table),"Only actual native table contact establishes support.");Assert.That(body.IsSleeping(),Is.True,"Original PhysX sleep settings remain unchanged.");for(int i=0;i<60;i++){Call(v,"TickLiquid",Time.fixedDeltaTime);yield return new WaitForFixedUpdate();}Assert.That(body.IsSleeping(),Is.True);Assert.That(Get(v,"LastSupport"),Is.SameAs(table));Assert.That((float)Get(v,"SupportAge"),Is.LessThan(.1f));Assert.That((int)Get(v,"NativeSupportPairs"),Is.GreaterThan(0));body.position+=new Vector3(18,4,0);body.transform.position=body.position;body.WakeUp();Physics.SyncTransforms();for(int i=0;i<12;i++){Call(v,"TickLiquid",Time.fixedDeltaTime);yield return new WaitForFixedUpdate();}Assert.That(Get(v,"LastSupport"),Is.Not.SameAs(table),"Native Exit or actual contact-point separation retires the binding; no stale infinite support cache.");Assert.That(body.mass,Is.EqualTo(mass));Assert.That((int[])Get(f.rules,"points"),Is.All.Zero,"Support fixture never injects a carrier, fill, serving or score.");f.match.enabled=true;}}
  [UnityTest,Timeout(90000)]public IEnumerator ActualSpoutIntoOpeningMissSpillAndNativeImpactBreak(){using(var f=new Fixture()){yield return f.Load();f.Start(1);Time.timeScale=2;yield return Until(()=>{f.Observe();return Get(f.arms[0],"Held")!=null;},35,"Real AI/native wrist contact must collect the actual teapot before a controlled stream fixture.");Time.timeScale=1;f.match.enabled=false;var arm=f.arms[0];var pot=Get(arm,"Held");Assert.That((bool)Get(pot,"pourable"),Is.True);Call(f.trucks[0],"TickDrive",Vector2.zero);Call(f.trucks[0],"Power",false);var cup=Get(f.cups[0],"vessel");float end=Time.realtimeSinceStartup+12;while((float)Get(cup,"Volume")<.3f&&Time.realtimeSinceStartup<end){var desired=Body(cup).position+Vector3.up*2.4f-Vector3.forward*.25f;var spout=(Transform)Get(pot,"spout");var grip=(Rigidbody)Get(arm,"grip");Call(arm,"Move",desired-(spout.position-grip.position),62f,false,Time.fixedDeltaTime);Call(pot,"TickLiquid",Time.fixedDeltaTime);yield return new WaitForFixedUpdate();}Assert.That((float)Get(cup,"Volume"),Is.GreaterThan(.25f),"Only an actual emitted stream intersecting the native round aperture can add tea.");Assert.That((int[])Get(f.rules,"points"),Is.All.Zero,"Pouring alone never fabricates a service.");float spill=(float)Get(pot,"SpilledVolume"),cupBefore=(float)Get(cup,"Volume");for(int i=0;i<90;i++){var spout=(Transform)Get(pot,"spout");var grip=(Rigidbody)Get(arm,"grip");Call(arm,"Move",Body(cup).position+Vector3.up*2.4f+Vector3.right*4-(spout.position-grip.position),62f,false,Time.fixedDeltaTime);Call(pot,"TickLiquid",Time.fixedDeltaTime);yield return new WaitForFixedUpdate();}Assert.That((float)Get(pot,"SpilledVolume"),Is.GreaterThan(spill));Assert.That((int[])Get(f.rules,"points"),Is.All.Zero);
   Call(arm,"Drop");var rb=Body(pot);rb.position=new Vector3(-45,12,-3);rb.rotation=Quaternion.identity;rb.transform.SetPositionAndRotation(rb.position,rb.rotation);rb.linearVelocity=Vector3.down*12;Physics.SyncTransforms();yield return Until(()=>(bool)Get(pot,"Broken"),4,"Actual hard native ground impact must use the single CoreCollapse health authority.");Assert.That(((Rigidbody[])Get(pot,"fragments")).Any(b=>b.gameObject.activeSelf&&!b.isKinematic),Is.True);Assert.That((float)Get(pot,"Volume"),Is.Zero);Assert.That((int[])Get(f.rules,"points"),Is.All.Zero);f.match.enabled=true;}}
  [UnityTest,Timeout(65000)]public IEnumerator OneThroughFourViewsAndFourSoftwareControllersKeepActualOwners(){using(var f=new Fixture()){yield return f.Load();Sports("SportsCameraOptions").GetMethod("Set").Invoke(null,new object[]{true});var views=Get(f.match,"drivingViews");Call(views,"Select",1);for(int n=1;n<=4;n++){f.Start(n);yield return null;yield return null;var rally=Get(views,"rally");Assert.That(((int[])Get(rally,"owners")).Take(n),Is.EqualTo(Enumerable.Range(0,n)));var cameras=(Camera[])Get(f.match,"cameras");Assert.That(cameras.Length,Is.EqualTo(n));Assert.That(cameras.Sum(c=>c.rect.width*c.rect.height),Is.EqualTo(1).Within(.001f));for(int i=0;i<n;i++){object[]args={i,-1,null,null};Assert.That((bool)f.match.GetType().GetMethod("TryReadViewportCard").Invoke(f.match,args),Is.True);Assert.That((int)args[1],Is.EqualTo(i));Assert.That((string)args[2],Is.EqualTo("0 PTS"));}}yield return Capture(f.match,"four-view-real-owner-cards-720",1280,720);Call(f.match,"SetupScreen");Set(Get(f.match,"setup"),"count",4);Call(f.match,"NormalizeSetup");var players=(Array)Get(Get(f.match,"setup"),"players");var pads=new Gamepad[4];for(int i=0;i<4;i++){pads[i]=f.Pad();var p=players.GetValue(i);Set(p,"source",Enum.Parse(p.GetType().GetField("source").FieldType,"WholeController"));Set(p,"pad",pads[i]);InputSystem.QueueStateEvent(pads[i],new GamepadState());}Assert.That((bool)Call(f.match,"StartMatch"),Is.True);yield return Until(()=>(bool)Get(f.rules,"Active"),8,"Real countdown and neutral input gate.");yield return null;var starts=f.trucks.Select(Body).Select(b=>b.position).ToArray();for(int i=0;i<4;i++)InputSystem.QueueStateEvent(pads[i],new GamepadState{rightTrigger=.8f}.WithButton(GamepadButton.RightShoulder));float until=Time.realtimeSinceStartup+2;while(Time.realtimeSinceStartup<until)yield return null;for(int i=0;i<4;i++){Assert.That(((Vector2[])Get(f.match,"commands"))[i].y,Is.GreaterThan(.7f));Assert.That(Vector3.Distance(starts[i],Body(f.trucks[i]).position),Is.Greate